create temp table _had_parking on commit drop as select id from public.areas where parking_lat is not null;
update public.areas set parking_lat=49.430981, parking_lng=-119.563642, parking_name='Skaha Bluffs main climbers'' lot at the end of Smythe Road (upper lot)' where path <@ (select path from public.areas where id='bc_skaha_bluffs') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 49.430981) / 2), 2) + cos(radians(49.430981)) * cos(radians(lat)) * power(sin(radians(lng - -119.563642) / 2), 2))) <= 4);
